WITH RECURSIVE days(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM days WHERE n<30), subjects(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM subjects WHERE n<20)
INSERT INTO app_active_days(subject_ref,active_date_utc) SELECT 'ph-app-subject-v1_' || printf('%064x',subjects.n), date('2026-11-10','-' || days.n || ' days') FROM days CROSS JOIN subjects;
WITH RECURSIVE days(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM days WHERE n<30), events(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM events WHERE n<10)
INSERT INTO broker_issue_success_events(issue_source,subject_ref,managed_credential_ref,observed_at) SELECT 'qq','ph-qq-subject-v1_synthetic-' || events.n,'synthetic-' || days.n || '-' || events.n,date('2026-11-10','-' || days.n || ' days') || 'T12:00:00.000Z' FROM days CROSS JOIN events;
WITH RECURSIVE days(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM days WHERE n<80)
INSERT INTO broker_daily_summary_deliveries(report_date_utc,status,lease_token,lease_expires_at,attempted_at,delivered_at) SELECT date('2026-11-10','-' || n || ' days'),'delivered','00000000-0000-0000-0000-000000000000',date('2026-11-10','-' || (n-1) || ' days') || 'T00:20:00.000Z',date('2026-11-10','-' || (n-1) || ' days') || 'T00:05:00.000Z',date('2026-11-10','-' || (n-1) || ' days') || 'T00:05:00.000Z' FROM days;
